export const STAGING: Readonly<Record<string, Staging>> = Object.freeze({
  'bear:scene:bear_arrival': { light: 'day', line: 'Exterior, cold clear morning. The foot of the mountains: a trail of earth and stones starts climbing toward snowy passes far away, between scattered firs and boulders; snow only on the heights. Wild and empty: no buildings, no structures, no lanterns, no banner anywhere; nobody waits for the company here.' },
  'bear:scene:bear_audience': { light: 'interior', line: 'Interior of the Bear chieftain’s hall, hewn into the mountain rock: a long low hall of rough granite under heavy dark timber beams, a glowing central fire pit, fur hides on the walls, carved bear reliefs on squat pillars, a massive stone seat at the far end. A few Bear banners hang near the seat. Indoors only: no sky, no window onto a landscape.' },
  'bear:scene:bear_raven_messenger': { light: 'day', line: 'Under snow-laden firs away from the trail, grey overcast day: a small clearing of pine needles and melting snow, the trail glimpsed between the trunks in the background. Wild forest only: no building or structure anywhere, even far away; no banner.' },
  'bear:scene:bear_trapped_miners': { light: 'day', line: 'Exterior mountainside by day, dust still settling: the mouth of a mine gallery blocked by a rockfall of big boulders, broken timber props sticking out of it; sacks of ore set on the ground to one side.' },
  'bear:scene:bear_raven_traps': { light: 'day', line: 'A narrow mountain trail between boulders, hard high-altitude daylight, snow along the edges: thin tripwires stretched across the path at ankle height, leather skins of powder tucked under stones. Wild mountainside only: no building or structure anywhere, even far away; no banner.' },
  'bear:scene:bear_outpost_gathering': { light: 'dusk', line: 'The courtyard of a small Bear outpost in a mountain pass at dusk: low walls of rough stone, one squat watchtower, guarded fires in braziers, the wind flattening their smoke. A single Bear banner above the gate. A small outpost, not a fortress or a city.' },
  'bear:refuge:bear-first-refuge': { samePlaceAs: 'bear:scene:bear_outpost_gathering', light: 'nightFire', line: 'The same small Bear outpost in a mountain pass at night: low rough stone walls, one squat watchtower, fires lit in braziers against the wind, the courtyard cleared for the company to rest. A single Bear banner above the gate. Not a fortress or a city.' },
  'bear:scene:bear_ore_convoy': { light: 'day', line: 'Overcast day, seen from a rocky lookout: a mountain road winding down from the mine galleries in hairpin bends to a stone bridge over a dry ravine, a milestone at the roadside, deep cart ruts with a few black stones fallen in them. No carts, no animals.' },
  'bear:scene:bear_ancient_relic': { light: 'interior', line: 'Underground, by the light of a single torch: a mine gallery collapsed long ago, rotten beams, fallen blocks, thick dust. In the middle ground, half buried in the dust, a small statuette of a rearing bear carved in dark stone, set with one red gem. No sky, no hanging crystal, no magic glow.' },
  'bear:scene:bear_sacred_mines': { light: 'day', line: 'Exterior, grey day: the entrance of the Bear’s sacred mine galleries hewn into a cliff face, great carved bears on either side. In front, the Raven’s worksite: tents, winches, empty carts, and Raven banners planted in front of the Bear carvings.' },
  'bear:scene:bear_pre_mines_defense': { light: 'interior', line: 'Deep underground inside the mine, no sky: a large timber-propped mine chamber with rails, a winch above a descending shaft, a barricade of overturned carts and crates, Raven banners nailed over carved Bear reliefs. Torchlight only.' },
  'bear:scene:bear_mines_defense_aftermath': { samePlaceAs: 'bear:scene:bear_pre_mines_defense', light: 'interior', line: 'Deep underground, the same timber-propped mine chamber after the fight, no sky: the barricade broken apart, Raven banners torn down on the floor, the carved Bear reliefs visible again, calm torchlight.' },
  'bear:scene:bear_pre_mines_seizure': { light: 'interior', line: 'Deeper underground, no sky: a Raven barricade of carts and crates across a mine gallery whose rails run down toward the back, where a dull black vein crosses the rock, still small and far away. Torchlight only.' },
  'bear:scene:bear_mines_seizure_aftermath': { samePlaceAs: 'bear:scene:bear_pre_mines_seizure', light: 'interior', line: 'Deep underground, the same gallery after the fight, no sky: the barricade broken, mine carts loaded with black stones, the dull black vein at the back. No banner anywhere.' },
  'bear:refuge:bear-second-refuge': { light: 'interior', line: 'Interior of the miners’ shelter near the galleries: a low room hewn in the rock, a smoky central hearth, straw pallets, tools hanging on the walls, lanterns. Cold stone and smoke. Indoors only: no sky.' },
  'bear:scene:bear_miners_testimony': { light: 'day', line: 'Pale early morning on a mountain trail coming down from the mine galleries toward the valleys: abandoned Raven carts on the roadside, miners’ tools laid on a rock. Open wild slopes: no fortress or town in view.' },
  'bear:scene:bear_mountain_shrine': { light: 'day', line: 'Daylight, wind and light snow: a small stone shrine set against the rock face with a carved bear; at its foot, offerings: miners’ tools, polished stones, a purse of old coins. Intimate and small: no temple, no grand stairway, no other building or structure in view.' },
  'bear:scene:bear_dark_vein': { light: 'interior', line: 'The very bottom of the mine galleries, deep underground, no sky: a rock wall crossed by a dull black vein that swallows the light of the torches set in the timber props; the shadows seem to ripple around it. No crystals, no purple glow.' },
  'bear:scene:bear_vigil': { light: 'nightFire', line: 'Night: a single campfire on a rocky ledge high in the mountains; far across the valley, the lit openings of the Bear chieftain’s hall carved into the mountainside, where the company will be judged tomorrow.' },
  'bear:refuge:bear-final-refuge': { samePlaceAs: 'bear:scene:bear_vigil', light: 'nightFire', line: 'Night: a single campfire on a rocky ledge high in the mountains; far across the valley, the lit openings of the Bear chieftain’s hall carved into the mountainside, where the company will be judged tomorrow.' },
  'bear:scene:bear_judgement': { light: 'interior', samePlaceAs: HALL, line: 'Interior of the Bear chieftain’s hall, the same hall as the audience: rough granite hewn into the rock, heavy timber beams, fur hides, carved bear reliefs, the fire pit burning lower; seen closer to the massive stone seat at the far end. A few Bear banners near the seat. Indoors only: no sky.' },
  'bear:surface:chronicle-end': { light: 'interior', samePlaceAs: HALL, line: 'Interior of the Bear chieftain’s hall after the judgement, the same hall as the audience: empty and quiet, embers glowing in the fire pit, the stone seat empty. Indoors only: no sky, no terrace.' },
  'bear:scene:bear_master_spy_pre_combat': { light: 'dusk', line: 'High galleries near the summits: a mine gallery opening onto the snowy peaks, the wind blowing snow inside, cold dusk light at the opening and torchlight within.' },
  'bear:scene:bear_master_spy_aftermath': { samePlaceAs: 'bear:scene:bear_master_spy_pre_combat', light: 'dusk', line: 'The same high mine gallery opening onto the snowy peaks, after the fight: overturned crates, snow settling, stillness, cold dusk light at the opening.' },
  'bear:scene:bear_borin_pre_combat': { light: 'day', line: 'Daylight: a cleared stone terrace before the Bear chieftain’s hall, open to the sky under the peaks, the hall’s heavy doors set in the rock behind, snow swept to the edges.' },
  'bear:scene:bear_trial_aftermath': { samePlaceAs: 'bear:scene:bear_borin_pre_combat', light: 'dusk', line: 'The same stone terrace before the Bear chieftain’s hall at sunset: trampled snow, broken spears on the ground.' },
  'bear:scene:bear_epilogue': { light: 'dusk', line: 'Dawn over the Mountains of Resilience seen from the high pass, the trail running down toward the distant lowlands. Calm, open and neutral.' },

  // The Dragon, awaiting the operator's validation (docs/content/drafts/DRAGON_STAGING_DRAFT_2026-11-12.md).
  // I · The foothills
  'dragon:scene:dragon_arrival': { light: 'day', line: 'Exterior, clear morning at the foot of the Celestial Peaks: a pilgrims’ trail of steps carved into pale rock starts climbing between pale boulders and wind-twisted pines; far above, needles of pale rock pierce the clouds, the highest mountains the company has ever seen. Wild and empty: no building or structure anywhere, no banner.' },
  [DRAGON_HALL]: { light: 'interior', skyVisible: true, line: 'Interior of the Dragon clan’s great hall, carved into a cliff of pale stone partway up the Peaks: a vast lofty hall whose tall round-arched openings look out over the rock needles and a sea of clouds, carved dragons coiling around the pillars, bronze braziers and thin threads of incense smoke, a broad stone dais at the far end. A few Dragon banners near the dais. Bright daylight through the openings.' },
  'dragon:scene:dragon_wolf_envoy': { light: 'day', line: 'A snowy shelf on the pilgrims’ trail in the foothills, cold daylight: a plain white truce flag on a pole planted in the snow and, far from it, a single axe stuck upright in the snow. Pale rocks and wind-twisted pines around. No building in view; the truce flag bears no emblem and there is no other banner.' },
  'dragon:scene:dragon_terrorized_village': { light: 'dusk', line: 'A small foothill hamlet late in the afternoon: a few low houses of pale stone roofed with stone slabs, doors barricaded with planks, barns shut tight, an empty livestock pen with a broken fence, straw scattered on trampled snow. A hamlet waiting for an attack: no rampart, no banner, and no castle, fortress, monastery or town anywhere in view, even far away.' },
  'dragon:scene:dragon_wolf_traps': { light: 'day', line: 'A low, close view up the snared steps of the pilgrims’ trail climbing the foothills by day, the viewpoint just above the snow at the foot of the climb: steps carved into pale rock under a thin layer of snow rise steeply away from the viewer and fill most of the frame, steel snares half hidden in the snow across the nearest steps, large in the foreground, small stacked-stone pilgrim cairns along the edge. The steps climb straight up the middle of the picture toward a shoulder of pale rock and wind-twisted pines that closes the view: only a little sky at the top, no sea of clouds beside the trail. Wild mountainside: no building or structure in view, no banner.' },
  [DRAGON_HERMITAGE]: { light: 'dusk', line: 'Dusk: a small hermitage of the Dragon clan built of pale stone, clinging to a sheer cliff face and reached by steps carved in the rock; a narrow terrace with a fire for travellers, a bronze bell hanging under a small round arch, a carved dragon above the door, a sea of clouds below turning rose. No banner.' },
  'dragon:refuge:dragon-first-refuge': { samePlaceAs: DRAGON_HERMITAGE, light: 'nightFire', line: 'Night at the same small hermitage of pale stone clinging to a sheer cliff face: the fire burning on the narrow terrace for the company to rest, lit windows, the bronze bell under its small round arch, the carved dragon above the door, stars above a sea of clouds. No banner.' },
  // II · The terraces
  'dragon:scene:dragon_captive_wolf': { light: 'day', line: 'Grey day at the edge of the terraces, seen from high above and looking steeply down onto them: stepped terraces cut into the mountainside with dry-stone retaining walls run across the whole width of the picture in stacked curving bands, one tier below the other, down to the last ledge above a drop into the clouds, which fill the top of the picture; on the nearest terrace, along the bottom of the picture, trampled snow with signs of a struggle at the foot of a wall. No trail running up one side, no slope on the left with a view on the right. No building, no bell, no carved stone, no banner.' },
  'dragon:scene:dragon_crystal_clues': { light: 'day', line: 'Daylight on the terraces, the carved wall seen face-on and close: a tall wall of pale rock, square to the viewer, fills almost the whole frame, covered with ancient carved inscriptions and engravings of dragons around a crystal, worn by the wind; along the bottom of the picture, the snowy terrace floor at its foot, where a faint glitter of crystal dust lies in the snow. Only a sliver of sky at the top: no distant peaks and no sea of clouds beside the wall. Carved glyphs only, no readable letters. No building, no banner.' },
  [WOLF_LAIR]: { light: 'interior', line: 'Interior of the Wolf clan’s lair, a great cave dug into the cliff: rough hide curtains, bones and wolf pelts, sharpened stakes, iron braziers, Wolf banners on crude poles. At the far end, on a crude altar of piled stones that is not the Dragon’s, the Echo Crystal shines: a clear crystal glowing a soft icy blue. Firelight and the crystal’s glow only. The Wolf’s own rough cave: no Dragon carvings, no carved stone pillars, no bronze bells.' },
  'dragon:scene:dragon_pre_lair_assault': { samePlaceAs: WOLF_LAIR, light: 'interior', line: 'Interior of the same Wolf lair, seen closer to the far end: hide curtains, wolf pelts, iron braziers, Wolf banners on crude poles, and the crude altar of piled stones where the Echo Crystal shines a soft icy blue. Firelight and the crystal’s glow only. The Wolf’s own rough cave: no Dragon carvings, no carved stone pillars, no bronze bells.' },
  'dragon:scene:dragon_pre_lair_seizure': { samePlaceAs: WOLF_LAIR, light: 'interior', line: 'Interior of the same Wolf lair, seen closer to the far end: hide curtains, wolf pelts, iron braziers, Wolf banners on crude poles, and the crude altar of piled stones where the Echo Crystal shines a soft icy blue. Firelight and the crystal’s glow only. The Wolf’s own rough cave: no Dragon carvings, no carved stone pillars, no bronze bells.' },
  'dragon:scene:dragon_lair_assault_aftermath': { samePlaceAs: WOLF_LAIR, light: 'interior', line: 'Interior of the same Wolf lair after the fight: overturned iron braziers, Wolf banners torn down on the floor, the Echo Crystal still glowing a soft icy blue on the crude altar, and at the back a dark passage leading away. The Wolf’s own rough cave: no Dragon carvings, no carved stone pillars, no bronze bells.' },
  'dragon:scene:dragon_lair_seizure_aftermath': { samePlaceAs: WOLF_LAIR, light: 'interior', line: 'Interior of the same Wolf lair after the fight: overturned iron braziers, Wolf banners torn down on the floor, the Echo Crystal still glowing a soft icy blue on the crude altar, and at the back a dark passage leading away. The Wolf’s own rough cave: no Dragon carvings, no carved stone pillars, no bronze bells.' },
  // III · The summits
  'dragon:refuge:dragon-second-refuge': { light: 'interior', line: 'Interior of the pilgrims’ shelter under the summits: a low vaulted room of pale stone with round arches, blankets and straw pallets, small niches with offerings and burning incense sticks whose smoke drifts in the lantern light, a carved dragon on the back wall. A closed, low room: no window and no opening onto the outside, lantern light only.' },
  'dragon:scene:dragon_shaman_traces': { light: 'day', line: 'A high camp of the Wolf clan above the lair, abandoned in haste, on an overcast cold day: hide tents left standing or collapsed, cold fire pits, scattered gear, a fallen Wolf banner in the snow. Set apart from the others, one open tent with cold ashes and strange black symbols traced on the ground, not the Wolf’s. No building.' },
  'dragon:scene:dragon_freed_pilgrims': { light: 'day', line: 'Clear morning on a high trail coming down from the Wolf’s lair, seen from below as it comes down toward the viewer: a symmetrical view up a narrow gully between two tall walls of pale rock that frame the left and right edges of the picture; the steps carved in the pale rock come down the middle of the gully from a notch high at the top centre, straight at the viewer and widening as they come closer, abandoned sacks of provisions and cut ropes lying on the steps, the nearest ones large in the foreground. The sky and a glimpse of the sea of clouds show only in the narrow notch at the top, never in a wide view to one side. No building, no bell, no carved wall, no banner.' },
  'dragon:scene:dragon_young_dragon': { light: 'day', line: 'Daylight high on a rock needle: a dragon’s nest in a hollow of the rock, lined with branches and shed scales, open to the sky above a sea of clouds. Empty: no creature in it. No building, no banner.' },
  'dragon:scene:dragon_crystal_altar': { light: 'dusk', line: 'The summit of the Peaks at cold dusk, above a sea of clouds: the Dragon’s altar of the Crystal, pale stone carved with coiling dragons, open to the sky and empty, split by a crack from which a black stain oozes, frozen like ink. No crystal on it, no purple glow, no banner.' },
  [DRAGON_VIGIL]: { light: 'nightFire', line: 'Night on a high ridge of the Peaks, the view looking out and steeply down from the ridge: a single campfire in the lee of a pale boulder close by, a starry sky, a sea of clouds silvered by the moon spreading far below the ridge. Far below the viewer, well beneath the horizon, a gap in the clouds shows a distant cliff where the Dragon clan’s great hall, where the company will be judged tomorrow, is only a handful of tiny warm lit openings in the rock, smaller than the campfire’s flames: no towers, no bridges, no palace outline. Nothing is built on the ridge or in the foreground: no wall, carved pillar or bell.' },
  'dragon:refuge:dragon-final-refuge': { samePlaceAs: DRAGON_VIGIL, light: 'nightFire', line: 'Night on a high ridge of the Peaks, the view looking out and steeply down from the ridge: a single campfire in the lee of a pale boulder close by, a starry sky, a sea of clouds silvered by the moon spreading far below the ridge. Far below the viewer, well beneath the horizon, a gap in the clouds shows a distant cliff where the Dragon clan’s great hall, where the company will be judged tomorrow, is only a handful of tiny warm lit openings in the rock, smaller than the campfire’s flames: no towers, no bridges, no palace outline. Nothing is built on the ridge or in the foreground: no wall, carved pillar or bell.' },
  // Before Kaelen
  'dragon:scene:dragon_judgement': { samePlaceAs: DRAGON_HALL, light: 'interior', skyVisible: true, line: 'Interior of the Dragon clan’s great hall, the same hall as the audience: pale stone, tall round-arched openings onto the rock needles and the clouds, carved dragons coiling around the pillars, bronze braziers burning lower; seen closer to the broad stone dais, late-afternoon light through the openings. A few Dragon banners near the dais.' },
  'dragon:surface:chronicle-end': { samePlaceAs: DRAGON_HALL, light: 'interior', skyVisible: true, line: 'Interior of the Dragon clan’s great hall after the judgement, the same hall as the audience: empty and quiet, bronze braziers cooling, the broad stone dais empty, a sunset sky and clouds through the tall round-arched openings.' },
  [SHAMAN_RIDGE]: { light: 'dusk', line: 'The highest summits at cold dusk: a narrow snowy ridge between rock needles above a sea of clouds, a trail of black stains like frozen ink across the snow and strange black symbols smeared on the rocks, leading up toward the top. No building, no banner.' },
  'dragon:scene:dragon_shaman_aftermath': { samePlaceAs: SHAMAN_RIDGE, light: 'dusk', line: 'The same narrow snowy ridge between rock needles after the fight: the black stains fading from the snow, stillness, the last light over the sea of clouds. No building, no banner.' },
  [DRAGON_ESPLANADE]: { light: 'day', line: 'Daylight: a wide stone esplanade before the Dragon clan’s great hall, on the cliff edge above the clouds, lined with pillars carved with coiling dragons, the hall’s tall round-arched entrance behind.' },
  'dragon:scene:dragon_trial_aftermath': { samePlaceAs: DRAGON_ESPLANADE, light: 'dusk', line: 'The same stone esplanade before the Dragon clan’s great hall at sunset: broken spears on the flagstones, scorch marks on the pale stone, the sea of clouds glowing below.' },
  'dragon:scene:dragon_epilogue': { light: 'dusk', line: 'Dawn seen from a natural rock lookout on the Celestial Peaks: the sun rising over a sea of clouds between the rock needles, wind-twisted pines on the rocks. Calm, open and neutral, and wild: no paved plaza, no mosaic, no building, no bell, no structure anywhere (unlike the altar of the summit).' },

  // The Scorpion, validated as is by the operator on 2026-11-12 (docs/content/drafts/SCORPION_STAGING_DRAFT_2026-11-12.md). A Phoenix
  // place shows no scorpion and a Scorpion place no phoenix; neighbouring desert scenes each keep their own framing.
  // I · The dunes
  'scorpion:scene:scorpion_arrival': { light: 'day', line: 'Exterior, late morning at the edge of the Arid Deserts, the sun already merciless: the last thorny scrub and cracked earth in the foreground give way to great dunes of honey-gold sand rolling away to a horizon blurred by heat haze, where a faint caravan track fades into the sand. Wild and empty: no building, ruin or structure anywhere, even far away, no banner, no oasis in view.' },
  [SCORPION_HALL]: { light: 'interior', skyVisible: true, line: 'Interior of the Grand Inquisiteur’s hall of records, a lofty hall of mud brick plastered with ochre clay: its walls are lined up to the ceiling with pigeonholes full of scroll cases and clay tablets, with wooden galleries and ladders along them; long writing tables with brass instruments, pierced copper lamps; hard sunlight falls in sharp dusty shafts through high latticed openings near the ceiling, with no view of any landscape. At the far end, a raised seat of dark wood under a carved scorpion, and a few Scorpion banners near it. No book on display, no codex, no lectern, no phoenix.' },
  'scorpion:scene:scorpion_scholars': { light: 'day', line: 'A camp of Scorpion scholars on the desert track toward the temple, mid-morning under a hard sun, seen from the track with tents on both sides: a few tents of undyed linen with brown stripes, folding writing tables with scrolls, clay tablets and ink pots, a tall wooden stake at the foot of the nearest tent with ropes coiled at its base, and a water jar set apart in the shade, out of reach. A single Scorpion banner on a pole. Dunes all around: no building, ruin or oasis in view, no phoenix.' },
  'scorpion:scene:scorpion_phoenix_faithful': { light: 'day', line: 'The road to the Phoenix temple across the desert, bright afternoon, a symmetrical view straight along the road: an old road of worn flagstones half drowned in drifting sand runs from the foreground straight away from the viewer between two low dunes; along both edges, small weathered standing stones carved with a phoenix, each bearing a small oil lamp lit in broad daylight. Wild desert around: no temple, building or ruin in view, even far away, no banner, no scorpion.' },
  'scorpion:scene:scorpion_sand_riddle': { light: 'day', line: 'Daylight, the riddle door seen face-on and close: a heavy stone door set in a wall of weathered sandstone half buried in drifting sand fills almost the whole frame, square to the viewer, covered with ancient carved signs around a carved riddle, a phoenix with spread wings carved above the lintel, a narrow dark slot at the edge of the door where a lever hides behind the stone; sand heaped at its foot along the bottom of the picture. Only a sliver of sky at the top: no distant view beside the wall. Carved glyphs only, no readable letters. A door of the Phoenix: no scorpion, no banner.' },
  [SCORPION_OASIS]: { light: 'dusk', line: 'Dusk at the oasis held by the Scorpion scholars: a pool of clear turquoise water ringed with date palms, a few low flat-roofed houses of ochre mud brick with carved wooden lattices and striped linen awnings, a stone well with a copper bucket, a shaded arcade where water jars stand in a row, a carved scorpion above a doorway. Far behind the palms, small in the distance, the first broken columns of old ruins against the copper sky. A small oasis, not a town: no rampart, no tower, no banner, no phoenix.' },
  'scorpion:refuge:scorpion-first-refuge': { samePlaceAs: SCORPION_OASIS, light: 'nightFire', line: 'Night at the same oasis of the Scorpion scholars: a fire burning by the turquoise pool for the company to rest, the date palms dark against a sky dense with stars, lit lattices in the low flat-roofed houses of ochre mud brick, water jars under the shaded arcade, the carved scorpion above a doorway. A small oasis, not a town: no rampart, no tower, no banner, no phoenix.' },
  // II · The ruins
  'scorpion:scene:scorpion_warded_path': { light: 'day', line: 'The road through the Phoenix ruins by day, seen from slightly above with the road crossing the picture from left to right: a road of worn flagstones between broken sandstone walls and toppled round columns half buried in sand; across it, in the foreground at the viewer’s feet, ward circles traced on the flagstones in glowing saffron lines, rings of interlaced signs that faintly smoulder. No standing building, no banner, no scorpion.' },
  'scorpion:scene:scorpion_buried_library': { light: 'interior', skyVisible: true, line: 'Interior of a library of the Phoenix half buried in sand: a long vaulted hall of carved sandstone whose deep wall niches still hold hundreds of rolled scrolls, phoenixes carved on the niche frames; a slope of sand poured in through a breach in the vault fills half the hall, and a single shaft of sunlight falls through the breach onto the sand, with no landscape visible. No book, no codex, no lectern, no scorpion, no banner.' },
  [PHOENIX_TEMPLE]: { light: 'interior', line: 'Interior of the Temple of the Phoenix: a long nave of ash-coloured sandstone between two rows of great round columns carved with phoenixes, saffron hangings between them, oil lamps burning in every niche though it is day outside; at the heart of the nave, on a round stone hearth, a tall flame burns saffron-orange with a white-hot heart, and before it, on a low stone lectern, rests the prophetic codex, open: a thick old codex bound in ash-grey leather with dull bronze clasps, lit by the flame, with no glow of its own. A closed nave lit by the flame and the lamps. The Phoenix’s own temple: no scorpion anywhere, no banner.' },
  'scorpion:scene:scorpion_pre_temple_assault': { samePlaceAs: PHOENIX_TEMPLE, light: 'interior', line: 'Interior of the same Temple of the Phoenix, seen closer to the heart of the nave: the round stone hearth where the saffron-orange flame burns with a white-hot heart, the prophetic codex open on its low stone lectern before it, bound in ash-grey leather with dull bronze clasps, columns carved with phoenixes and lamps burning in their niches on either side. A closed nave lit by the flame and the lamps. The Phoenix’s own temple: no scorpion anywhere, no banner.' },
  'scorpion:scene:scorpion_pre_temple_seizure': { samePlaceAs: PHOENIX_TEMPLE, light: 'interior', line: 'Interior of the same Temple of the Phoenix, seen closer to the heart of the nave: the round stone hearth where the saffron-orange flame burns with a white-hot heart, the prophetic codex open on its low stone lectern before it, bound in ash-grey leather with dull bronze clasps, columns carved with phoenixes and lamps burning in their niches on either side. A closed nave lit by the flame and the lamps. The Phoenix’s own temple: no scorpion anywhere, no banner.' },
  'scorpion:scene:scorpion_temple_assault_aftermath': { samePlaceAs: PHOENIX_TEMPLE, light: 'interior', line: 'Interior of the same Temple of the Phoenix after the fight: the flame still burning saffron-orange on its round stone hearth at the heart of the nave, the low stone lectern before it empty, the codex gone, oil lamps knocked over and oil spilled on the flagstones, a broken spear among them. A closed nave lit by the flame and the remaining lamps. The Phoenix’s own temple: no book anywhere, no scorpion, no banner.' },
  'scorpion:scene:scorpion_temple_seizure_aftermath': { samePlaceAs: PHOENIX_TEMPLE, light: 'interior', line: 'Interior of the same Temple of the Phoenix after the fight: the flame still burning saffron-orange on its round stone hearth at the heart of the nave, the low stone lectern before it empty, the codex gone, oil lamps knocked over and oil spilled on the flagstones, a broken spear among them. A closed nave lit by the flame and the remaining lamps. The Phoenix’s own temple: no book anywhere, no scorpion, no banner.' },
  'scorpion:refuge:scorpion-second-refuge': { light: 'interior', line: 'Interior of the caravan shelter near the temple: a low vaulted room of mud brick, rugs and saddle bags along the walls, water skins hanging from pegs, coils of rope, warm sand swept into the corners, a small brazier of incense whose smoke drifts in the light of a copper lamp. A shelter for any traveller: no emblem of any clan, no banner, no scorpion, no phoenix.' },
  // III · The sanctuary
  'scorpion:scene:scorpion_prophet_traces': { light: 'interior', line: 'Interior of a narrow cell set apart from the Phoenix temple, emptied in haste: bare sandstone walls, a straw pallet thrown aside, an overturned stool, an open empty chest, and loose leaves of paper scattered across the floor, each covered with dense cramped writing in cold black ink, unreadable; a single forgotten oil lamp still burning on the floor. Bare walls: no carving, no emblem, no scorpion, no banner, no book.' },
  'scorpion:scene:scorpion_temple_witnesses': { light: 'day', line: 'Hard morning light on a path leaving the Phoenix temple, seen from below as it comes down a long dune toward the viewer: a track of footprints and scattered flagstones descends straight from the dune crest at the top of the picture toward the viewer, widening as it comes closer, a fallen saffron scarf in the sand in the foreground. Far behind the crest, small and distant, only the tops of the temple’s round columns show against the pale sky. No other building, no banner, no scorpion.' },
  [ASH_SANCTUARY]: { light: 'interior', line: 'Interior of a sanctuary of the Phoenix dug into the rock: a rough-hewn chamber of red-brown rock, a great round basin cut into the floor and filled with grey sacred ash under which red embers still glow, a phoenix with spread wings carved in the rock wall above it, smoke-darkened niches with unlit lamps; lit only by the warm red glow of the embers. The Phoenix’s own sanctuary: no scorpion anywhere, no banner.' },
  'scorpion:scene:scorpion_corrupted_texts': { samePlaceAs: ASH_SANCTUARY, light: 'interior', line: 'Interior of the same sanctuary of the Phoenix dug into the rock, seen at its far end: a low niche cut into the rock wall where a single torn page lies, its lines written in a cold black ink that seems to stain the stone around it; far behind, out of focus, the faint red glow of the basin of ash. No book, no purple glow, no scorpion, no banner.' },
  [SCORPION_VIGIL]: { light: 'nightFire', line: 'Night in the desert, in the lee of a dune: a single campfire beside the empty doorway of a small, half-ruined mud-brick shelter, a sky dense with stars, dunes silvered by the moon rolling away. Far away across the dunes, low on the horizon, a few tiny warm lit windows where the Grand Inquisiteur will judge the company tomorrow, smaller than the campfire’s flames: no towers, no walls, no city outline. No lamp at the doorway, no banner.' },
  'scorpion:refuge:scorpion-final-refuge': { samePlaceAs: SCORPION_VIGIL, light: 'nightFire', line: 'Night in the desert, in the lee of a dune: a single campfire beside the empty doorway of a small, half-ruined mud-brick shelter, a sky dense with stars, dunes silvered by the moon rolling away. Far away across the dunes, low on the horizon, a few tiny warm lit windows where the Grand Inquisiteur will judge the company tomorrow, smaller than the campfire’s flames: no towers, no walls, no city outline. No lamp at the doorway, no banner.' },
  // Before the Grand Inquisiteur
  'scorpion:scene:scorpion_judgement': { samePlaceAs: SCORPION_HALL, light: 'interior', skyVisible: true, line: 'Interior of the Grand Inquisiteur’s hall of records, the same hall as the audience: ochre clay walls lined with pigeonholes of scroll cases and clay tablets, wooden galleries and ladders, long writing tables; seen closer to the raised seat of dark wood under the carved scorpion at the far end, late-afternoon sunlight falling in long amber shafts through the high latticed openings, with no view of any landscape. A few Scorpion banners near the seat. No book on display, no codex, no lectern, no phoenix.' },
  'scorpion:surface:chronicle-end': { samePlaceAs: SCORPION_HALL, light: 'interior', skyVisible: true, line: 'Interior of the Grand Inquisiteur’s hall of records after the judgement, the same hall as the audience: empty and quiet, the raised seat empty, the copper lamps unlit, the last light of sunset in faint shafts through the high latticed openings where dust floats, with no view of any landscape. No book on display, no codex, no phoenix.' },
  [PROPHET_DUNE]: { light: 'dusk', line: 'Dusk in the deep dunes, seen along a long knife-edge dune crest that rises diagonally from the foreground toward the top of the picture: a trail of cold black ink stains across the sand, and loose leaves of paper covered with black writing scattered along the crest, some lifting in the wind, leading away toward the last copper light. Wild and empty: no building, ruin or structure anywhere, no banner.' },
  'scorpion:scene:scorpion_prophet_aftermath': { samePlaceAs: PROPHET_DUNE, light: 'dusk', line: 'The same long knife-edge dune crest after the fight: the black ink stains fading into the sand, the loose leaves settled and half buried, stillness, the last light. Wild and empty: no building, ruin or structure anywhere, no banner.' },
  [SCORPION_COURTYARD]: { light: 'day', line: 'Daylight in the walled courtyard of the Grand Inquisiteur’s house of records: a square of sun-baked flagstones enclosed by shaded arcades of ochre mud brick with carved wooden lattices, a dry stone basin in the middle, and behind it the tall doorway of the hall of records under a carved scorpion, a single Scorpion banner above it. Only the sky shows above the arcades. No phoenix.' },
  'scorpion:scene:scorpion_trial_aftermath': { samePlaceAs: SCORPION_COURTYARD, light: 'dusk', line: 'The same walled courtyard of the Grand Inquisiteur’s house of records at sunset: broken staffs and scattered clay tablets on the flagstones, scorch marks on the stone, long amber light across the arcades. Only the sky shows above the arcades. No phoenix.' },
  'scorpion:scene:scorpion_epilogue': { light: 'dusk', line: 'Dawn seen from a natural outcrop of red sandstone above the Arid Deserts: the sun rising over endless rippled dunes, long blue shadows in their hollows, a lone thorn tree on the rocks. Calm, open and neutral, and wild: no paved place, no mosaic, no building, ruin or structure anywhere.' },
});

/** Looks of the characters redone with the staging, validated with it (beasts: proposals the canon does not describe). */
export const STAGED_LOOKS: Readonly<Record<string, string>> = Object.freeze({
  'bear:actor:bear_miner': 'A civilian miner of the Bear clan, not a soldier: a leather hood and a cloth wrapped against the dust cover his face, a leather apron over plain wool, a pickaxe on his shoulder, a lantern at his belt, rock dust on his clothes. No armour, no sword, no shield.',
  'bear:enemy:corrupted_beast': 'A great four-legged mountain beast, massive, shaggy and with curved horns, driven mad: black veins showing under its fur, burning eyes, foam at the mouth. Not a bear and not a wolf. Nothing specific to one clan: it must fit any mountain land.',
  'bear:enemy:depth_beast': 'A blind creature of the deep mine galleries, pale-skinned, with long digging claws and a back bristling with shards of black stone.',
  // The Dragon's characters, PROPOSALS awaiting the operator's validation. Kaelen is a human elder, the operator's choice of
  // 2026-11-12 (« Ancien humain »); the details of his look stay a proposal.
  'dragon:actor:kaelen': 'PROPOSAL, to confirm: the very old human chief of the Dragon clan (a man, not a dragon), tall and thin, a long pale robe embroidered with scales of verdigris bronze, a closed mask-helm of verdigris bronze shaped like a dragon’s head that hides his face, a long staff topped with a coiled dragon. No crystal, orb or gem anywhere on him or his staff: the Echo Crystal is not his.',
  'dragon:actor:dragon_guardian': 'PROPOSAL, to confirm: a guardian warrior of the Dragon clan, a closed bronze helm shaped like a dragon’s head, scale armour of verdigris bronze over pale cloth, a long spear with a broad blade.',
  'dragon:actor:dragon_villager': 'PROPOSAL, to confirm: a civilian villager of the foothills, not a soldier: a hood and a wool scarf cover his face, a sheepskin vest over plain wool, a herder’s staff. No armour, no weapon.',
  'dragon:actor:dragon_pilgrim': 'PROPOSAL, to confirm: a civilian pilgrim of the Dragon, not a soldier: a deep hood and a cloth veil cover the face, a long pale travelling robe, a walking staff, a small bundle on the back. No armour, no weapon.',
  'dragon:actor:wolf_envoy': 'PROPOSAL, to confirm: a warrior of the Wolf clan sent as an envoy: a wolf-pelt hood whose wolf’s head hides his face, grey furs over leather, a plain white truce flag on a pole in his hand and no weapon at all.',
  'dragon:actor:wolf_captive': 'PROPOSAL, to confirm: a wounded warrior of the Wolf clan: a wolf-pelt hood whose wolf’s head hides his face, torn furs and leather, bandages, standing hunched with one hand on his side, no weapon.',
  'dragon:actor:wolf_chief': 'PROPOSAL, to confirm: the chief of the Wolf clan, a massive warrior: a helm crowned with a great wolf’s head and pelt that hides his face, heavy grey furs over blackened iron mail, bone trophies, a great two-handed axe.',
  'dragon:actor:shadow_shaman': 'PROPOSAL, to confirm: a shaman of the Shadows, come from nobody knows where, belonging to no clan: no wolf pelt, no emblem. A tattered dark robe, a deep hood with at most two glowing eyes in its shadow, black streaks like frozen ink on the hands and the hem, strange symbols painted on the robe, a crooked staff. No purple glow.',
  'dragon:enemy:wolf_raider': 'PROPOSAL, to confirm: a raider of the Wolf clan: a wolf-pelt hood that hides the face, furs and leather, a hand axe and a small round shield.',
  'dragon:enemy:wolf_hunter': 'PROPOSAL, to confirm: a hunter of the Wolf clan: a grey fur hood and a cloth mask hide the face, leather and furs, a sling in hand and a leather pouch of stones at the belt. No bow and no quiver.',
  'dragon:enemy:wolf_champion': 'PROPOSAL, to confirm: an elite champion of the Wolf clan: a closed iron helm with a crest of wolf’s ears, a wolf pelt over the shoulders, chain mail, several throwing blades: short throwing knives at his belt and on a bandolier across the chest, one held in hand. No long sword.',
  'dragon:enemy:shadow_wyrm': 'PROPOSAL, to confirm: a wyrm of the summits, a long wingless kin of the Western dragons with four short legs and pale scales, no whiskers and no mane, driven mad by a dark energy: pure black veins like frozen ink running between its scales, eyes burning a cold pale white. No purple, violet or magenta anywhere. Not the young dragon.',
  // The Scorpion's characters, proposals validated as is by the operator on 2026-11-12 (docs/content/drafts/SCORPION_STAGING_DRAFT_2026-11-12.md).
  // Each carries its combat weapon (src/combat/legacyCombatRuntime.js); nobody carries a book that could pass for the codex.
  'scorpion:actor:grand_inquisitor': 'PROPOSAL, to confirm: the Grand Inquisiteur, chief of the Scorpion clan and a formidable scholar, a man, tall, upright and lean, of an age nobody can guess behind his mask: layered robes of deep umber and rust over undyed linen, their hems embroidered with fine dark copper lines like the segments of a scorpion’s tail; a high hood over a smooth closed mask of dark copper, finely engraved, that hides his whole face; a long staff of dark wood whose copper head curves forward like a scorpion’s raised stinger, the focus of his magic; scroll cases and a wax tablet at his belt. No book, no crystal, orb or gem. Never purple.',
  'scorpion:actor:scorpion_scholar': 'PROPOSAL, to confirm: a scholar of the Scorpion clan, not a warrior: a loose robe of undyed linen with a rust sash and a deep rust hood, a linen veil wrapped over the whole face under the hood, a plain wooden staff in hand, leather scroll cases and a clay tablet hanging at the belt, a small dark copper scorpion brooch on the chest. No armour, no book. Never purple.',
  'scorpion:actor:phoenix_faithful': 'PROPOSAL, to confirm: a civilian faithful of the Phoenix clan, not a soldier and unarmed: a long saffron and ash-grey robe, a deep hood and a cloth veil that cover the face, a phoenix embroidered on the chest, holding up a small clay oil lamp lit in broad daylight. No armour, no weapon, no book.',
  'scorpion:actor:phoenix_captive': 'PROPOSAL, to confirm: a civilian faithful of the Phoenix clan held captive by the scholars, not a soldier and unarmed: a torn and dusty saffron robe, a hood and a cloth veil that cover his face, a frayed rope still tied around his wrists, standing hunched and exhausted by thirst. No armour, no weapon.',
  'scorpion:actor:phoenix_guardian_chief': 'PROPOSAL, to confirm: the chief of the Phoenix temple’s guardians, a massive warrior: a closed helm of ash-grey steel shaped like a phoenix’s head, with a crest of steel flame feathers, that hides his face; heavy armour of ash-grey steel over a saffron tabard embroidered with a phoenix; a long spear whose blade burns with a saffron flame, his weapon. No crimson, no gold.',
  'scorpion:actor:shadow_prophet': 'PROPOSAL, to confirm: the Prophet of the Shadows, a stranger who belongs to no clan: no emblem of any clan, no phoenix and no scorpion. A long robe of dust grey and black, a deep hood with at most two cold glowing eyes in its shadow, hands black to the wrists as if dipped in ink, and from one raised open hand a curling wave of cold black ink, his weapon. No staff, no book, no pages. No purple glow.',
  'scorpion:enemy:phoenix_guardian': 'PROPOSAL, to confirm: a guardian of the Phoenix temple: a closed helm of ash-grey steel with a small crest of steel flame feathers, armour of ash-grey steel scales over a saffron tunic, a small phoenix on the chest, a long temple spear with a leaf-shaped blade. No crimson, no gold.',
  'scorpion:enemy:phoenix_flamekeeper': 'PROPOSAL, to confirm: an elite flame warden of the Phoenix temple, tall and heavily armoured: a closed helm of ash-grey steel shaped like a phoenix’s head that hides the face, a long saffron mantle over plate armour, and in both hands a tall iron staff topped with a brazier cup where the temple’s flame burns saffron-orange with a white-hot heart, his weapon. No spear, no sword. No crimson, no gold.',
  'scorpion:enemy:shadow_zealot': 'PROPOSAL, to confirm: an elite faithful of the Phoenix led astray under the Shadows’ sway, tall and gaunt: a tattered saffron robe blackened and soaked with cold black ink, without any emblem, a deep hood with at most two cold glowing eyes in its shadow, a cracked and extinguished clay lamp hanging at the belt, and a curling wave of cold black ink rising from the outstretched hands, the weapon. No steel weapon. No purple glow.',
});

/**
 * A plateau's POIs stand at the positions of their Lion counterparts, so its atlas keeps the Lion atlas's layout: the
 * first Bear atlases, drawn freely, put the markers on cliffs and rivers. The Lion atlas, letterboxed by
 * tools/art/atlas_layout.py, is sent as the layout to repaint; the result is cropped back to the Lion atlas's frame.
 */
export const ATLAS_LAYOUTS: Readonly<Record<string, { lionAtlas: string; line: string }>> = Object.freeze({
  'bear:atlas:1': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/lion-opening.png',
    line: 'Region I of the Bear’s mountains: the first passes of the Mountains of Resilience, from the foot of the mountains up to the small Bear outpost in a pass.' },
  'bear:atlas:2': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/bois-clair.png',
    line: 'Region II of the Bear’s mountains: the road of the sacred mines, climbing to the carved entrance of the Bear’s sacred galleries, with winches and mine works along it.' },
  'bear:atlas:3': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/judgement.png',
    line: 'Region III of the Bear’s mountains: the high ground above the deep galleries, with mine shafts and gallery mouths, and the Bear chieftain’s hall carved into a cliff.' },
  'dragon:atlas:1': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/lion-opening.png',
    line: 'Region I of the Celestial Peaks: the foothills, with the pilgrims’ trail climbing from a small barricaded hamlet toward the Dragon clan’s great hall and a hermitage clinging to a cliff. The tents at the top of the layout become the small barricaded hamlet: a few low houses of pale stone roofed with stone slabs, doors barricaded with planks, beside its clearing. The palisaded camp with tents on the right of the layout is not kept: its clearing stays open, and at its edge stands the hermitage, a small building of pale stone with a flat terrace roof, its back against a sheer cliff face, reached by steps cut in the rock, with no palisade, no stockade, no wooden tower and no tents around it. The tents on the left of the layout are not kept: the foot of the trail stays wild. No palisade and no tents anywhere on this map.' },
  'dragon:atlas:2': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/bois-clair.png',
    line: 'Region II of the Celestial Peaks: stepped terraces cut along the mountainside, the ridge road, a carved rock wall of the ancients, and the Wolf clan’s lair dug into a cliff behind its stake palisade.' },
  'dragon:atlas:3': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/judgement.png',
    line: 'Region III of the Celestial Peaks: the summits above the clouds, with the Wolf’s abandoned high camp, the pilgrims’ shelter, the old altar on the summit, cracked and empty, and a Dragon hall carved into a cliff. The altar is a bare slab of pale stone split by a crack, with nothing on it. Nothing on this map glows: no crystal anywhere, no shrine of light, no blue or cyan glow.' },
  // The Scorpion, validated as is by the operator on 2026-11-12. The tool turns every stream of a layout into an icy torrent; each
  // desert line overrides it, as it names what each site of the Lion layout becomes and forbids any other camp or temple.
  'scorpion:atlas:1': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/lion-opening.png',
    line: 'Region I of the Arid Deserts: the dunes, from the edge of the desert to the oasis held by the Scorpion scholars. In this desert the layout’s streams and waterfalls do not become icy torrents: they become dry riverbeds of cracked pale clay and sand with no water at all, and the wooden bridge becomes a stone causeway over a dry ravine. Forests become dunes and thorny scrub, cliffs become red-brown sandstone outcrops and mesas, clearings become flat pans of packed sand and gravel, roads become caravan tracks. The fortified castle on the left of the layout becomes the Grand Inquisiteur’s house of records: a compact walled compound of ochre mud brick with flat roofs, one square tower and a shaded courtyard, not a Gothic castle. The crossroads in the middle becomes the scholars’ camp: three small tents of undyed linen beside the track, without the stone cross. The palisaded camp on the right of the layout becomes the oasis: a small turquoise pool ringed with date palms and a few low flat-roofed houses of mud brick, with no palisade, no wooden tower and no tents. Near the right edge, beside a junction of tracks, one small stone door is set into a low rock outcrop. The tents at the top and on the left of the layout are not kept: their clearings stay bare sand along the track, and the foot of the trail stays wild. The oasis pool is the only water on this map. No other camp, temple, ruin or settlement anywhere on this map.' },
  'scorpion:atlas:2': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/bois-clair.png',
    line: 'Region II of the Arid Deserts: the ruins of the Phoenix and its temple. In this desert the layout’s river and streams do not become icy torrents: they become a wide dry riverbed of cracked pale clay and sand with dry side channels and no water at all; the great stone bridge stays, in weathered sandstone, over the dry riverbed, and the smaller crossings become stone fords and causeways. Forests become dunes and thorny scrub, cliffs become red-brown sandstone outcrops, clearings become flat pans of sand, and low broken sandstone walls and toppled round columns half buried in sand line the roads. The walled village on the right of the layout becomes the Temple of the Phoenix: one long temple of ash-coloured cut sandstone with great round columns, a thin plume of smoke rising from its flame, a paved forecourt with braziers, with no village houses, no palisade and no steeple. The small chapel on the rock at the top becomes the entrance of the buried library: a few column tops and a doorway emerging from a sand dune, no chapel. The fenced tent at the top right becomes the caravan shelter: one low vaulted building of mud brick beside the road, with no fence and no tents. The fenced tent at the top left is not kept: bare sand. No other temple, camp or settlement anywhere on this map.' },
  'scorpion:atlas:3': { lionAtlas: 'public/assets/generated/lion-phase/poi-lot-e/judgement.png',
    line: 'Region III of the Arid Deserts: the sanctuary of the ashes and the Grand Inquisiteur’s house of records. In this desert the layout’s streams and waterfalls do not become icy torrents: they become dry ravines of red rock and sand with no water at all, and the arched stone bridges become plain sandstone bridges over the dry ravines. Forests become dunes and thorny scrub, cliffs become red-brown sandstone outcrops and mesas. The Gothic ruins along the roads become low broken sandstone walls and toppled round columns half buried in sand, with no Gothic arches and no pointed windows. The great ruined palace at the top right becomes the Grand Inquisiteur’s house of records, intact: a walled compound of ochre mud brick with flat roofs, one square tower and a courtyard. The ruined arches at the top in the middle become the entrance of the sanctuary of the ashes: a dark doorway cut into a red rock face, with no building around it. In the clearing among the ruins on the left, one small lone cell of sandstone. The tents at the bottom right become the vigil: one small half-ruined mud-brick shelter with a campfire, and no tents. The palisaded camp at the top left is not kept: bare sand. Nothing on this map glows but that campfire: no glowing sanctuary, no shrine of light. No other temple, camp or settlement anywhere on this map.' },
});
